import{_ as t,a as s,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Forgot Password","description":"","frontmatter":{"outline":false,"examples":[{"id":"forgot-password","title":"Forgot Password","description":"Request a password reset email.","request":"POST /api/shop/forgot-passwords\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\n\\n{\\n  \\"email\\": \\"john@example.com\\"\\n}\\n","response":"{\\n  \\"message\\": \\"Reset password link has been sent to your email\\"\\n}\\n","commonErrors":[{"error":"404 Not Found","cause":"Email address not found","solution":"Verify the email is associated with an account"},{"error":"400 Bad Request","cause":"Invalid email format","solution":"Provide valid email address"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customers/forgot-password.md","filePath":"api/rest-api/shop/customers/forgot-password.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/shop/customers/forgot-password.md"};function i(n,e,d,h,l,c){return a(),s("div",null,e[0]||(e[0]=[o(`<h1 id="forgot-password" tabindex="-1">Forgot Password <a class="header-anchor" href="#forgot-password" aria-label="Permalink to &quot;Forgot Password&quot;">​</a></h1><p>Request a password reset email. A reset link will be sent to the customer&#39;s email address.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/forgot-passwords</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr></tbody></table><p>This endpoint is public — it takes the storefront key but no customer token, since the shopper cannot sign in at this point.</p><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;john@example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="request-parameters" tabindex="-1">Request Parameters <a class="header-anchor" href="#request-parameters" aria-label="Permalink to &quot;Request Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>email</code></td><td>string</td><td>Yes</td><td>Email address associated with account</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>success</code></td><td>boolean</td><td><code>true</code> when the reset mail was queued. <code>false</code> when the address is unregistered or the request was throttled.</td></tr><tr><td><code>message</code></td><td>string</td><td><code>Reset link sent successfully to your email</code>, or <code>Email address not found</code> on either failure path.</td></tr></tbody></table><p>Both outcomes answer with HTTP <code>200</code> — read <code>success</code>, not the status code.</p><h2 id="the-reset-link" tabindex="-1">The Reset Link <a class="header-anchor" href="#the-reset-link" aria-label="Permalink to &quot;The Reset Link&quot;">​</a></h2><p>The mail carries a storefront URL of the form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yourstore.com/reset-password/{token}</span></span></code></pre></div><p>Opening it renders the store&#39;s reset form; submitting that form sets the new password. The token is single-use, is invalidated once the reset completes, and is superseded when a newer reset request is made for the same address.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Reset link from a login screen</strong> — post the email the shopper typed; a <code>success</code> of <code>true</code> means the mail was queued, and the shopper completes the reset on the storefront web page the link points to.</li><li><strong>Distinguish &quot;sent&quot; from &quot;not sent&quot; in the UI</strong> — the endpoint always answers <code>200</code>; branch on the <code>success</code> field, never on the status code.</li></ul><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ol><li>The endpoint is public — it takes the storefront key and no customer token.</li><li>A reset link is mailed to the address when it belongs to a registered customer. The link is valid for <strong>60 minutes</strong>.</li><li>Repeating the request for the same address inside <strong>60 seconds</strong> is throttled and no second mail goes out.</li><li>A throttled repeat and an unregistered address return the same body — <code>success: false</code> with the message <code>Email address not found</code>. The message does not distinguish the two, so do not surface it as proof that an address is unregistered.</li><li>The reset itself happens on the storefront web page carried in the mail. The API exposes no endpoint that consumes the reset token, so a headless client cannot complete the flow in-app.</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Show one neutral confirmation whatever the response says</strong> — the two failure paths are indistinguishable, and echoing &quot;not found&quot; tells an attacker which addresses are registered.</li><li><strong>Back off for a minute before retrying</strong> — a resend inside the throttle window silently returns the failure message rather than sending a second mail.</li><li><strong>Send the customer to the web reset page</strong> — a native app has to open the emailed link in a browser; there is no API counterpart.</li><li><strong>Use <a href="/api/rest-api/shop/customers/change-password.html">Change Password</a> when the customer is logged in</strong> — that path takes the current password and needs no email round-trip.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customers/change-password.html">Change Password</a> — rotate the password of a logged-in customer</li><li><a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> — authenticate and receive a customer token</li><li><a href="/api/rest-api/shop/customers/customer-registration.html">Customer Registration</a> — create an account and receive a token</li></ul>`,26)]))}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
